import{_ as a,o as i,c as r,O as t}from"./chunks/framework.db831a78.js";const h=JSON.parse('{"title":"Spring 全家桶","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/04-Spring全家桶.md","filePath":"interview/后端/Java/04-Spring全家桶.md","lastUpdated":null}'),o={name:"interview/后端/Java/04-Spring全家桶.md"};function n(l,e,s,c,p,u){return i(),r("div",null,e[0]||(e[0]=[t('<h1 id="spring-全家桶" tabindex="-1">Spring 全家桶 <a class="header-anchor" href="#spring-全家桶" aria-label="Permalink to &quot;Spring 全家桶&quot;">​</a></h1><blockquote><p>常问等级：★★★ 高频必考 / ★★☆ 中频常见 / ★☆☆ 低频了解</p></blockquote><h2 id="ioc-容器原理-bean-完整生命周期-★★★" tabindex="-1">IOC 容器原理；Bean 完整生命周期 ★★★ <a class="header-anchor" href="#ioc-容器原理-bean-完整生命周期-★★★" aria-label="Permalink to &quot;IOC 容器原理；Bean 完整生命周期 ★★★&quot;">​</a></h2><ul><li>IOC（控制反转）：对象的创建与依赖注入交给容器，通过配置/注解声明，容器反射实例化并注入。</li><li>生命周期：实例化 → 属性注入（依赖注入）→ Aware 回调（BeanNameAware 等）→ BeanPostProcessor 前置 → @PostConstruct → InitializingBean.afterPropertiesSet → 自定义 init → BeanPostProcessor 后置（AOP 在此生成代理）→ 使用 → @PreDestroy → DisposableBean.destroy → 自定义 destroy。</li></ul><h2 id="bean-作用域-beanfactory-与-applicationcontext-区别-★★★" tabindex="-1">Bean 作用域；BeanFactory 与 ApplicationContext 区别 ★★★ <a class="header-anchor" href="#bean-作用域-beanfactory-与-applicationcontext-区别-★★★" aria-label="Permalink to &quot;Bean 作用域；BeanFactory 与 ApplicationContext 区别 ★★★&quot;">​</a></h2><ul><li>作用域：singleton（默认，单例）、prototype（每次新建）、request/session/application（Web）、websocket。</li><li>BeanFactory 是底层接口，懒加载（首次 getBean 才创建）；ApplicationContext 扩展了它，启动时预实例化单例、支持国际化/事件/AOP/资源加载等，功能更全。</li></ul><h2 id="aop-原理-jdk-动态代理、cglib-五种通知-★★★" tabindex="-1">AOP 原理：JDK 动态代理、CGLIB；五种通知 ★★★ <a class="header-anchor" href="#aop-原理-jdk-动态代理、cglib-五种通知-★★★" aria-label="Permalink to &quot;AOP 原理：JDK 动态代理、CGLIB；五种通知 ★★★&quot;">​</a></h2><ul><li>JDK 动态代理：基于接口，Proxy.newProxyInstance + InvocationHandler；CGLIB：字节码生成子类，无需接口。</li><li>规则：目标实现接口默认 JDK 代理（可配置强制 CGLIB，SpringBoot2 默认 CGLIB）；CGLIB 不能代理 final 方法。</li><li>通知：@Before 前置、@After 后置（无论如何执行）、@AfterReturning 返回后、@AfterThrowing 异常、@Around 环绕（最强，控制是否调用目标）。</li></ul><h2 id="transactional-传播行为、隔离级别-事务失效场景-实现原理-★★★" tabindex="-1">@Transactional；传播行为、隔离级别；事务失效场景；实现原理 ★★★ <a class="header-anchor" href="#transactional-传播行为、隔离级别-事务失效场景-实现原理-★★★" aria-label="Permalink to &quot;@Transactional；传播行为、隔离级别；事务失效场景；实现原理 ★★★&quot;">​</a></h2><ul><li>传播行为 7 种：REQUIRED（默认，有则加入无则新建）、REQUIRES_NEW（挂起当前新建）、SUPPORTS、NOT_SUPPORTED、MANDATORY、NEVER、NESTED。</li><li>隔离级别：DEFAULT、READ_UNCOMMITTED、READ_COMMITTED、REPEATABLE_READ（MySQL 默认）、SERIALIZABLE。</li><li>失效场景：方法非 public、同类内部自调用（this 调用绕开代理）、异常被 try-catch 吞掉、抛出非 RuntimeException（默认只回滚 RuntimeException/Error，可用 rollbackFor 指定）、数据库引擎不支持事务（MyISAM）。</li><li>原理：基于 AOP 动态代理 + ThreadLocal 绑定事务，TransactionInterceptor 控制开启/提交/回滚。</li></ul><h2 id="springboot-自动配置原理-条件注解-启动流程-★★★" tabindex="-1">SpringBoot 自动配置原理；条件注解；启动流程 ★★★ <a class="header-anchor" href="#springboot-自动配置原理-条件注解-启动流程-★★★" aria-label="Permalink to &quot;SpringBoot 自动配置原理；条件注解；启动流程 ★★★&quot;">​</a></h2><ul><li>自动配置：@SpringBootApplication 含 @EnableAutoConfiguration → @Import(AutoConfigurationImportSelector) → 读取 <code>META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports</code>（旧为 <code>spring.factories</code>）加载配置类，按条件注解生效。</li><li>条件注解：@ConditionalOnClass/MissingBean/Property/ConditionalOnWebApplication 等。</li><li>启动流程：new SpringApplication → 推断 web 类型 → 初始化 ApplicationContext → 刷新容器 → 内嵌 Tomcat 启动 → 执行 Runner。</li></ul><h2 id="全局异常处理-★★★" tabindex="-1">全局异常处理 ★★★ <a class="header-anchor" href="#全局异常处理-★★★" aria-label="Permalink to &quot;全局异常处理 ★★★&quot;">​</a></h2><ul><li>@ControllerAdvice + @ExceptionHandler 统一捕获；结合 @ResponseBody 或 @RestControllerAdvice；自定义业务异常 + 错误码统一返回；可加 @ExceptionHandler 处理特定异常、兜底 Exception。</li><li>Filter/Interceptor 也可拦截，但业务异常推荐用全局异常处理器。</li></ul><h2 id="configuration、-bean-★★☆" tabindex="-1">@Configuration、@Bean ★★☆ <a class="header-anchor" href="#configuration、-bean-★★☆" aria-label="Permalink to &quot;@Configuration、@Bean ★★☆&quot;">​</a></h2><ul><li>@Configuration 声明配置类，其内 @Bean 方法经 CGLIB 增强保证单例（多次调用同一 Bean 返回同一实例）；@Bean 标注方法产物由容器管理，id 默认方法名。</li></ul><h2 id="springmvc-请求流程-filter-与-interceptor-区别-requestparam-与-requestbody-★★★" tabindex="-1">SpringMVC 请求流程；Filter 与 Interceptor 区别；@RequestParam 与 @RequestBody ★★★ <a class="header-anchor" href="#springmvc-请求流程-filter-与-interceptor-区别-requestparam-与-requestbody-★★★" aria-label="Permalink to &quot;SpringMVC 请求流程；Filter 与 Interceptor 区别；@RequestParam 与 @RequestBody ★★★&quot;">​</a></h2><ul><li>流程：DispatcherServlet → HandlerMapping 找到 Controller → HandlerAdapter 调 handler → 返回 ModelAndView → ViewResolver 渲染（或 @ResponseBody 直接写 JSON）。</li><li>Filter 基于 Servlet 规范，在容器级、作用于所有请求，只访问 request/response；Interceptor 基于 Spring AOP，在 handler 前后，可访问 handler 与 ModelAndView。执行顺序：Filter → Interceptor → Controller。</li><li>@RequestParam 取 URL 查询参数/表单字段（可单个或 Map）；@RequestBody 读请求体反序列化为对象（JSON）。</li></ul><h2 id="微服务-nacos-eureka、feign、gateway、sentinel、分布式事务-★★★" tabindex="-1">微服务：Nacos/Eureka、Feign、Gateway、Sentinel、分布式事务 ★★★ <a class="header-anchor" href="#微服务-nacos-eureka、feign、gateway、sentinel、分布式事务-★★★" aria-label="Permalink to &quot;微服务：Nacos/Eureka、Feign、Gateway、Sentinel、分布式事务 ★★★&quot;">​</a></h2><ul><li>Nacos/Eureka：注册中心，Eureka 是 AP（自我保护、无法及时剔除坏节点），Nacos 支持 AP/CP 切换、兼具配置中心。</li><li>Feign：声明式 HTTP 客户端，基于接口 + 动态代理 + Ribbon/LoadBalancer 负载均衡；超时需调 connectTimeout/readTimeout，并注意与 Hystrix/Sentinel 超时协调。</li><li>Gateway：基于 WebFlux/Netty 的网关，核心 Route（路由）、Predicate（断言匹配）、Filter（过滤器，可在转发前后处理）。</li><li>Sentinel：熔断降级 + 限流，规则含流控（QPS/线程数、直接/关联/链路）、降级、热点、系统规则。</li><li>分布式事务：见「分布式 &amp; 高并发」篇（2PC/TCC/SAGA/消息最终一致等）。</li></ul><h2 id="autowired-与-resource-区别-★★★" tabindex="-1">@Autowired 与 @Resource 区别 ★★★ <a class="header-anchor" href="#autowired-与-resource-区别-★★★" aria-label="Permalink to &quot;@Autowired 与 @Resource 区别 ★★★&quot;">​</a></h2><ul><li>@Autowired 是 Spring 注解，默认按 byType 注入，配合 @Qualifier 指定名称，required=false 允许为空。</li><li>@Resource 是 JSR-250，默认按 byName，找不到再 byType。</li></ul><h2 id="三级缓存解决循环依赖-★★★" tabindex="-1">三级缓存解决循环依赖 ★★★ <a class="header-anchor" href="#三级缓存解决循环依赖-★★★" aria-label="Permalink to &quot;三级缓存解决循环依赖 ★★★&quot;">​</a></h2><ul><li>三级缓存：singletonObjects（成品）、earlySingletonObjects（提前暴露）、singletonFactories（ObjectFactory 可生成代理/原始对象引用）。</li><li>A 依赖 B、B 依赖 A：A 实例化后提前暴露工厂，B 注入 A 的半成品引用，解决循环依赖；仅对 singleton + setter 注入有效，构造器注入循环无法解决（可用 @Lazy 打破）。</li></ul><h2 id="aop-失效场景-同类调用-★★☆" tabindex="-1">AOP 失效场景（同类调用）★★☆ <a class="header-anchor" href="#aop-失效场景-同类调用-★★☆" aria-label="Permalink to &quot;AOP 失效场景（同类调用）★★☆&quot;">​</a></h2><ul><li>同类内部方法自调用（this.a() 调 this.b()）不经过代理，b 的切面不生效；解决：注入自身代理、AopContext.currentProxy()、拆分到不同 Bean。</li></ul><h2 id="spring-用到的设计模式-★★☆" tabindex="-1">Spring 用到的设计模式 ★★☆ <a class="header-anchor" href="#spring-用到的设计模式-★★☆" aria-label="Permalink to &quot;Spring 用到的设计模式 ★★☆&quot;">​</a></h2><ul><li>工厂（BeanFactory）、单例（默认作用域）、代理（AOP）、模板方法（JdbcTemplate、RestTemplate）、观察者（事件机制）、适配器（HandlerAdapter）、策略（资源解析）、装饰器（BeanWrapper）等。</li></ul><h2 id="spring-boot-starter-机制、mybatis-与-★★★" tabindex="-1">Spring Boot Starter 机制、MyBatis #{} 与 ${} ★★★ <a class="header-anchor" href="#spring-boot-starter-机制、mybatis-与-★★★" aria-label="Permalink to &quot;Spring Boot Starter 机制、MyBatis #{} 与 ${} ★★★&quot;">​</a></h2><ul><li>Starter：把某功能依赖 + 自动配置类打包（spring-boot-starter-web 等），开箱即用；约定大于配置。</li><li>MyBatis：#{} 预编译占位符（?），防 SQL 注入；${} 字符串拼接，有注入风险，仅用于表名/列名/order by 等无法参数化的场景。</li></ul><h2 id="spring、springboot、springcloud-区别-前端转全栈必考-★★★" tabindex="-1">Spring、SpringBoot、SpringCloud 区别（前端转全栈必考）★★★ <a class="header-anchor" href="#spring、springboot、springcloud-区别-前端转全栈必考-★★★" aria-label="Permalink to &quot;Spring、SpringBoot、SpringCloud 区别（前端转全栈必考）★★★&quot;">​</a></h2><ul><li>Spring：核心框架，提供 IOC（依赖注入）与 AOP，但配置繁琐，需要大量 XML/注解手动装配。</li><li>SpringBoot：对 Spring 的封装与增强，提供「自动配置 + 起步依赖（Starter）+ 内嵌服务器」，约定大于配置，快速搭建独立运行的 Spring 应用。</li><li>SpringCloud：基于 SpringBoot 构建的微服务生态/工具集，解决分布式问题：注册中心（Nacos/Eureka）、配置中心、网关（Gateway）、服务调用（Feign）、熔断限流（Sentinel）、分布式事务等。</li><li>一句话：Spring 是地基，SpringBoot 是快速建房，SpringCloud 是城市基础设施；后端面试常让你辨析三者定位。</li></ul>',32)]))}const g=a(o,[["render",n]]);export{h as __pageData,g as default};
